// Des: Benchmark: run a URL list through the ladder, report cost per good page
// Flo: read list (L<level> <url>) > dry-run prints plan and worst case > live fetches each URL > tally per tier and vendor > text table > append dated section to a file
// I/O: --list file (caller) > table on stdout, optional section in --out file; dry-run unless --live
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const runz = @import("ct-ctrl-runz.zig"); const ladd = @import("ru-tier-ladd.zig"); const pipe = @import("ru-page-fetc.zig"); const brwx = @import("ct-ctrl-brow.zig");
pub const Item = struct { leve: u8, urlz: []const u8 };
pub const Rslt = struct { leve: u8, urlz: []const u8, good: bool, tier: i64, vend: []const u8, cred: u32, micr: u64, errz: []const u8 };
pub fn listRead(aren: std.mem.Allocator, text: []const u8) ![]const Item { var list: std.ArrayList(Item) = .empty; var itrz = std.mem.splitScalar(u8, text, '\n'); while (itrz.next()) |rawz| { const lnzz = std.mem.trim(u8, rawz, " \t\r"); if (lnzz.len == 0 or lnzz[0] == '#') continue; const spzz = std.mem.findScalar(u8, lnzz, ' ') orelse return error.BadUsage; if (lnzz[0] != 'L' and lnzz[0] != 'l') return error.BadUsage; const lvzz = std.fmt.parseInt(u8, lnzz[1..spzz], 10) catch return error.BadUsage; if (lvzz < 1 or lvzz > 9) return error.BadUsage; try list.append(aren, .{ .leve = lvzz, .urlz = std.mem.trim(u8, lnzz[spzz + 1 ..], " \t") }); } return list.toOwnedSlice(aren); }
pub fn bencRunz(aren: std.mem.Allocator, ladz: *ladd.Ladd, items: []const Item) ![]const Rslt { const outp = try aren.alloc(Rslt, items.len); for (items, 0..) |itzz, ind3| { if (ladz.sess) |sszz| { if (ind3 % 8 == 7) sszz.reset(); } if (ladd.laddFetc(ladz, aren, itzz.urlz)) |oczz| { const good = std.mem.eql(u8, oczz.stat, "new") or std.mem.eql(u8, oczz.stat, "same") or std.mem.eql(u8, oczz.stat, "notm"); outp[ind3] = .{ .leve = itzz.leve, .urlz = itzz.urlz, .good = good, .tier = oczz.tier, .vend = oczz.vend, .cred = oczz.cred, .micr = oczz.micr, .errz = if (good) "" else oczz.stat }; } else |err3| { outp[ind3] = .{ .leve = itzz.leve, .urlz = itzz.urlz, .good = false, .tier = 0, .vend = "", .cred = 0, .micr = 0, .errz = @errorName(err3) }; } } return outp; }
pub fn bencText(aren: std.mem.Allocator, rslt: []const Rslt, date: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; try outp.print(aren, "## Bench {s}\n| Level | URLs | Good | Hit rate | Cost per good page (micro-USD) |\n|---|---|---|---|---|\n", .{date}); var lvzz: u8 = 1; while (lvzz <= 9) : (lvzz += 1) { var tot2: u32 = 0; var gdzz: u32 = 0; var micz: u64 = 0; for (rslt) |rszz| { if (rszz.leve != lvzz) continue; tot2 += 1; micz += rszz.micr; if (rszz.good) gdzz += 1; } if (tot2 == 0) continue; try outp.print(aren, "| L{d} | {d} | {d} | {d}% | {d} |\n", .{ lvzz, tot2, gdzz, gdzz * 100 / tot2, if (gdzz > 0) micz / gdzz else 0 }); } try outp.appendSlice(aren, "| Tier / vendor | Good | Credits | Micro-USD |\n|---|---|---|---|\n"); const keys = [_][]const u8{ "", "deco", "zenr", "brig", "brow" }; var tier: i64 = 1; while (tier <= 4) : (tier += 1) { for (keys) |kyzz| { var gdzz: u32 = 0; var crzz: u32 = 0; var micz: u64 = 0; for (rslt) |rszz| { if (!rszz.good or rszz.tier != tier or !std.mem.eql(u8, rszz.vend, kyzz)) continue; gdzz += 1; crzz += rszz.cred; micz += rszz.micr; } if (gdzz == 0) continue; try outp.print(aren, "| T{d} {s} | {d} | {d} | {d} |\n", .{ tier, if (kyzz.len == 0) "own" else kyzz, gdzz, crzz, micz }); } } for (rslt) |rszz| { if (!rszz.good) try outp.print(aren, "- failed L{d}: {s} ({s})\n", .{ rszz.leve, rszz.urlz, rszz.errz }); } return outp.toOwnedSlice(aren); }
fn dayzText(aren: std.mem.Allocator, nowz: i64) ![]u8 { const eszz = std.time.epoch.EpochSeconds{ .secs = @intCast(@divFloor(nowz, 1000)) }; const ydzz = eszz.getEpochDay().calculateYearDay(); const mdzz = ydzz.calculateMonthDay(); return std.fmt.allocPrint(aren, "{d}-{d:0>2}-{d:0>2}", .{ ydzz.year, @intFromEnum(mdzz.month), mdzz.day_index + 1 }); }
pub fn runzBenc(ctx2: *const ctx3.Ctxz) !u8 { if (ctx2.args.list.len == 0) return error.BadUsage; const tex2 = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, ctx2.args.list, ctx2.allo, .limited(1 << 20)) catch return error.BadUsage; const items = try listRead(ctx2.allo, tex2); var perz = @as([10]u32, @splat(0)); for (items) |itzz| perz[itzz.leve] += 1; if (!ctx2.args.live) { const estz = runz.estzWors(ctx2.conf, ctx2.args.geoz); var thin: u32 = 0; for (perz[1..]) |cnzz| { if (cnzz == 1) thin += 1; } try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "dry-run | bench {d} URLs | worst case {d} credits ({d} micro-USD) per URL | {d} levels have only 1 URL (use 2+) | add --live to run", .{ items.len, estz.cred, estz.micr, thin })); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); var real = try ctx3.realMake(ctx2); var brwz = try brwx.brwzMake(ctx2, ""); defer if (brwz) |*bwzz| bwzz.deinit(); var ladz: ladd.Ladd = .{ .gpaz = ctx2.init.gpa, .iozz = ctx2.iozz, .conf = ctx2.conf, .dbzz = &dbzz, .dirz = ctx2.dirz, .back = real.bac2(), .gozz = ctx2.args.forc, .geoz = ctx2.args.geoz, .sess = if (brwz) |*bwzz| bwzz else null }; const rslt = try bencRunz(ctx2.allo, &ladz, items); const secz = try bencText(ctx2.allo, rslt, try dayzText(ctx2.allo, pipe.nowzMill(ctx2.iozz))); try ctx3.outz(ctx2, secz); if (ctx2.args.outz.len > 0) { const oldz = std.Io.Dir.cwd().readFileAlloc(ctx2.iozz, ctx2.args.outz, ctx2.allo, .limited(4 << 20)) catch ""; const allz = try std.fmt.allocPrint(ctx2.allo, "{s}\n{s}", .{ oldz, secz }); try std.Io.Dir.cwd().writeFile(ctx2.iozz, .{ .sub_path = ctx2.args.outz, .data = allz }); } return 0; }
